                    <h2 id="attendance-GETapi-v1-courses--course_id--attendance">Attendance for a class date (admin, course lecturer)</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>



<span id="example-requests-GETapi-v1-courses--course_id--attendance">
<blockquote>Example request:</blockquote>


<div class="bash-example">
