                                <h2 id="courses-GETapi-v1-courses">List courses</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Available to every authenticated user.</p>

<span id="example-requests-GETapi-v1-courses">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost:8000/api/v1/courses?search=algorithms&amp;lecturer_id=1&amp;per_page=15" \
    --header "Authorization: Bearer {ACCESS_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"search\": \"b\",
    \"lecturer_id\": 16,
    \"per_page\": 2
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/courses"
);

const params = {
    "search": "algorithms",
    "lecturer_id": "1",
    "per_page": "15",
};
Object.keys(params)
    .forEach(key =&gt; url.searchParams.append(key, params[key]));

const headers = {
    "Authorization": "Bearer {ACCESS_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "search": "b",
    "lecturer_id": 16,
    "per_page": 2
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

