                <h1 id="enrollments-grades">Enrollments & Grades</h1>

    

                                <h2 id="enrollments-grades-GETapi-v1-enrollments">List enrollments</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Scoped by role: admins see all, lecturers see enrollments in their courses,
students see their own (including grades).</p>

<span id="example-requests-GETapi-v1-enrollments">
<blockquote>Example request:</blockquote>


<div class="bash-example">
