                    <h2 id="enrollments-grades-PUTapi-v1-enrollments--enrollment_id--grade">Grade an enrollment</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Allowed for admins and the lecturer teaching the course. The letter grade is derived
from the score: A ≥ 85, B ≥ 70, C ≥ 55, D ≥ 40, otherwise E.</p>

