                    <h2 id="enrollments-grades-POSTapi-v1-enrollments">Enroll in a course</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Students enroll themselves (<code>student_id</code> is ignored); admins must provide <code>student_id</code>.</p>

<span id="example-requests-POSTapi-v1-enrollments">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/enrollments" \
    --header "Authorization: Bearer {ACCESS_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"student_id\": 16,
    \"course_id\": 16,
    \"academic_year\": \"6425\\/5931\",
    \"semester\": \"even\"
