                    <h2 id="enrollments-grades-POSTapi-v1-courses--course_id--grades-import">Bulk import grades from CSV (admin, course lecturer)</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Upload a CSV with the header <code>nim,score</code> (max 1000 rows, 1 MB). Valid rows are graded; invalid rows
are returned in <code>errors</code> with their line number and do not stop the import.</p>

<span id="example-requests-POSTapi-v1-courses--course_id--grades-import">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/courses/16/grades/import" \
    --header "Authorization: Bearer {ACCESS_TOKEN}" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "academic_year=2025/2026"\
    --form "semester=odd"\
    --form "file=@/private/var/folders/9t/1hc6rn451mvdt6p53mv3n8140000gn/T/github-copilot-oRrOVA/php27v20psoavpi5edu4Yl" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/courses/16/grades/import"
);

const headers = {
    "Authorization": "Bearer {ACCESS_TOKEN}",
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('academic_year', '2025/2026');
body.append('semester', 'odd');
body.append('file', document.querySelector('input[name="file"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

