                    <h2 id="student-profile-PATCHapi-v1-profile">Update my contact and address (student)</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Only <code>phone</code>, <code>address</code> (street), <code>postal_code</code> and the four region codes can be changed.
Region codes are all-or-nothing and must belong together; send all four as null to clear them.</p>

<span id="example-requests-PATCHapi-v1-profile">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost:8000/api/v1/profile" \
    --header "Authorization: Bearer {ACCESS_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"phone\": \"bngzmiyvdljnikhw\",
    \"address\": \"a\",
    \"postal_code\": \"69775\",
    \"province_code\": \"architecto\",
    \"regency_code\": \"architecto\",
    \"district_code\": \"architecto\",
    \"village_code\": \"architecto\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/profile"
);

const headers = {
    "Authorization": "Bearer {ACCESS_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "phone": "bngzmiyvdljnikhw",
    "address": "a",
    "postal_code": "69775",
    "province_code": "architecto",
    "regency_code": "architecto",
    "district_code": "architecto",
    "village_code": "architecto"
};

fetch(url, {
    method: "PATCH",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

