                <h1 id="timetable">Timetable</h1>

    

                                <h2 id="timetable-GETapi-v1-timetable">My timetable</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Admins see every slot, lecturers the slots of their courses, students the slots of courses
they are enrolled in for the same term. Ordered by weekday and start time.</p>

<span id="example-requests-GETapi-v1-timetable">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost:8000/api/v1/timetable?academic_year=2025%2F2026&amp;semester=odd" \
    --header "Authorization: Bearer {ACCESS_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"academic_year\": \"bngzmiy\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/timetable"
);

const params = {
    "academic_year": "2025/2026",
    "semester": "odd",
};
Object.keys(params)
    .forEach(key =&gt; url.searchParams.append(key, params[key]));

const headers = {
    "Authorization": "Bearer {ACCESS_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "academic_year": "bngzmiy"
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

