                    <h2 id="timetable-POSTapi-v1-courses--course_id--schedules">Add a schedule slot (admin)</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Rejected with 422 if the room is already booked for an overlapping time in that term.</p>

<span id="example-requests-POSTapi-v1-courses--course_id--schedules">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/courses/16/schedules" \
    --header "Authorization: Bearer {ACCESS_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"academic_year\": \"6425\\/5931\",
    \"semester\": \"odd\",
    \"day_of_week\": 1,
    \"start_time\": \"03:51\",
    \"end_time\": \"2052-11-22\",
    \"room\": \"n\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/courses/16/schedules"
);

const headers = {
    "Authorization": "Bearer {ACCESS_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "academic_year": "6425\/5931",
    "semester": "odd",
    "day_of_week": 1,
    "start_time": "03:51",
    "end_time": "2052-11-22",
    "room": "n"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

